PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT,preferred_language TEXT DEFAULT 'es',subscription_plan TEXT DEFAULT 'free',terms_version TEXT,terms_accepted_at TEXT,privacy_version TEXT,privacy_accepted_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE cases(id TEXT PRIMARY KEY,user_id TEXT,data_domain TEXT NOT NULL CHECK(data_domain IN ('personal','synthetic')),preparation_track TEXT NOT NULL CHECK(preparation_track IN ('uscis_affirmative','eoir_court','unknown','fictional')),country_of_fear TEXT,primary_language TEXT,interpreter_language TEXT,interview_date TEXT,hearing_date TEXT,local_only INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE documents(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,document_type TEXT NOT NULL,original_filename TEXT,local_storage_reference TEXT,processing_status TEXT NOT NULL DEFAULT 'pending',language TEXT,page_count INTEGER,user_confirmed_type INTEGER DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE source_items(id TEXT PRIMARY KEY,case_id TEXT,source_type TEXT NOT NULL CHECK(source_type IN ('user_statement','user_document','synthetic_case','country_condition','official_educational','ai_inference')),title TEXT,publisher TEXT,url TEXT,publication_date TEXT,event_date TEXT,retrieved_at TEXT,verified INTEGER DEFAULT 0,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE people(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,role_type TEXT,display_label TEXT,relationship_to_user TEXT,description TEXT,user_confirmed INTEGER DEFAULT 0,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE organizations(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,organization_type TEXT,name_or_label TEXT,description TEXT,user_confirmed INTEGER DEFAULT 0,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE facts(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,fact_type TEXT NOT NULL,value_text TEXT,value_json TEXT,source_item_id TEXT,source_locator TEXT,extraction_confidence REAL,user_confirmed INTEGER DEFAULT 0,user_disputed INTEGER DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE,FOREIGN KEY(source_item_id) REFERENCES source_items(id));
CREATE TABLE events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,event_type TEXT NOT NULL,title TEXT,approximate_date TEXT,date_precision TEXT CHECK(date_precision IN ('exact','approximate','month_only','year_only','relative','unknown')),location TEXT,description TEXT,source_item_id TEXT,chronology_order INTEGER,user_confirmed INTEGER DEFAULT 0,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE incidents(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,event_id TEXT,incident_type TEXT,location TEXT,harm_description TEXT,threat_present INTEGER,physical_harm INTEGER,detention INTEGER,medical_treatment INTEGER,reported_to_authorities INTEGER,government_actor INTEGER,non_state_actor INTEGER,user_stated_reason TEXT,current_relevance TEXT,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES events(id));
CREATE TABLE travel_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,country TEXT NOT NULL,event_type TEXT,event_date TEXT,date_precision TEXT,status_or_reason TEXT,return_to_feared_country INTEGER DEFAULT 0,source_item_id TEXT,user_confirmed INTEGER DEFAULT 0,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE questions(id TEXT PRIMARY KEY,category TEXT NOT NULL,subcategory TEXT,question_en TEXT NOT NULL,question_es TEXT NOT NULL,question_type TEXT NOT NULL,difficulty TEXT NOT NULL,objective TEXT,uscis_enabled INTEGER DEFAULT 1,court_enabled INTEGER DEFAULT 1,direct_enabled INTEGER DEFAULT 0,cross_enabled INTEGER DEFAULT 0,ij_enabled INTEGER DEFAULT 0,active INTEGER DEFAULT 1,version TEXT NOT NULL);
CREATE TABLE interviews(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,mode TEXT NOT NULL,role TEXT NOT NULL,language TEXT NOT NULL,started_at TEXT,ended_at TEXT,question_count INTEGER DEFAULT 0,status TEXT DEFAULT 'created',FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE interview_answers(id TEXT PRIMARY KEY,interview_id TEXT NOT NULL,question_id TEXT,transcript TEXT,answer_language TEXT,response_duration_ms INTEGER,uncertainty_marker TEXT,created_at TEXT NOT NULL,FOREIGN KEY(interview_id) REFERENCES interviews(id) ON DELETE CASCADE);
CREATE TABLE consistency_flags(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,classification TEXT NOT NULL CHECK(classification IN ('MATCH','APPROXIMATE_MATCH','REVIEW','POSSIBLE_DIFFERENCE','NEW_INFORMATION','INSUFFICIENT_INFORMATION')),importance_level INTEGER CHECK(importance_level BETWEEN 1 AND 4),topic TEXT,source_a TEXT,source_b TEXT,description TEXT,resolved INTEGER DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE topic_coverage(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,topic_code TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('NOT_PRACTICED','INTRODUCED','PARTIALLY_EXPLORED','PRACTICED','REVIEW_RECOMMENDED')),evidence_json TEXT,last_updated_at TEXT NOT NULL,UNIQUE(case_id,topic_code),FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE practice_reports(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,interview_id TEXT,report_json TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE synthetic_case_metadata(case_id TEXT PRIMARY KEY,scenario_title TEXT NOT NULL,country TEXT NOT NULL,difficulty TEXT NOT NULL,learning_objectives_json TEXT NOT NULL,intentional_features_json TEXT NOT NULL,disclaimer_version TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE INDEX idx_events_case ON events(case_id); CREATE INDEX idx_facts_case ON facts(case_id); CREATE INDEX idx_questions_category ON questions(category); CREATE INDEX idx_coverage_case ON topic_coverage(case_id);
